type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let len = a.len();

    // Assumption guarantees: len == r or len == c, and r, c > 0

    if len == r {
        // Broadcast array as column vector: each row i is a row of C copies of a[i]
        let mut matrix = Vec::with_capacity(r);
        for i in 0..r {
            let val = a[i];
            let row = vec![val; c];
            matrix.push(row);
        }
        matrix
    } else {
        // len == c
        // Broadcast array as row vector: each row is a clone of a
        let mut matrix = Vec::with_capacity(r);
        for _ in 0..r {
            matrix.push(a.clone());
        }
        matrix
    }
}